create extension if not exists pgcrypto;
create table if not exists public.ra_rooms(id uuid primary key default gen_random_uuid(),name text not null,host_id uuid not null,phase text not null default 'lobby',skill text not null default 'vocal',selected jsonb not null default '{}'::jsonb,nominees jsonb not null default '{}'::jsonb,skips text[] not null default '{}',prep_until timestamptz,break_until timestamptz,ready boolean not null default false,updated_at timestamptz default now());
create table if not exists public.ra_invites(room_id uuid primary key references public.ra_rooms(id) on delete cascade,judge_token text not null unique,candidate_token text not null unique);
create table if not exists public.ra_members(room_id uuid references public.ra_rooms(id) on delete cascade,user_id uuid not null,display_name text not null,role text not null check(role in ('host','judge','candidate')),joined_at timestamptz default now(),primary key(room_id,user_id));
create table if not exists public.ra_tracks(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.ra_rooms(id) on delete cascade,title text not null,category text not null check(category in ('vocal','rap','expression','pitch-high','pitch-low')),path text not null,created_at timestamptz default now());
create table if not exists public.ra_votes(room_id uuid not null references public.ra_rooms(id) on delete cascade,category text not null,judge_id uuid not null,track_id uuid not null references public.ra_tracks(id) on delete cascade,primary key(room_id,category,judge_id));
create table if not exists public.ra_scores(room_id uuid not null references public.ra_rooms(id) on delete cascade,skill text not null,judge_id uuid not null,values jsonb not null,submitted boolean not null default false,primary key(room_id,skill,judge_id));
create table if not exists public.ra_appeals(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.ra_rooms(id) on delete cascade,user_id uuid not null,body text not null,created_at timestamptz default now());
create or replace function public.ra_is_member(r uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.ra_members where room_id=r and user_id=auth.uid())$$;
create or replace function public.ra_is_host(r uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.ra_members where room_id=r and user_id=auth.uid() and role='host')$$;
create or replace function public.ra_is_judge(r uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.ra_members where room_id=r and user_id=auth.uid() and role in ('host','judge'))$$;
create or replace function public.ra_create_room(p_name text,p_display text) returns uuid language plpgsql security definer set search_path=public as $$declare rid uuid;begin if auth.uid() is null then raise exception 'Login required';end if;insert into public.ra_rooms(name,host_id) values(left(coalesce(nullif(trim(p_name),''),'Audition'),100),auth.uid()) returning id into rid;insert into public.ra_invites(room_id,judge_token,candidate_token) values(rid,replace(pg_catalog.gen_random_uuid()::text,'-','') || replace(pg_catalog.gen_random_uuid()::text,'-',''),replace(pg_catalog.gen_random_uuid()::text,'-','') || replace(pg_catalog.gen_random_uuid()::text,'-',''));insert into public.ra_members(room_id,user_id,display_name,role) values(rid,auth.uid(),left(coalesce(nullif(trim(p_display),''),'Host'),60),'host');return rid;end$$;
create or replace function public.ra_join_room(p_token text,p_display text) returns uuid language plpgsql security definer set search_path=public as $$declare rid uuid; rr text;begin if auth.uid() is null then raise exception 'Login required';end if;select room_id,case when judge_token=p_token then 'judge' else 'candidate' end into rid,rr from public.ra_invites where judge_token=p_token or candidate_token=p_token limit 1;if rid is null then raise exception 'Invalid invitation';end if;if exists(select 1 from public.ra_members where room_id=rid and user_id=auth.uid()) then return rid;end if;if rr='candidate' and exists(select 1 from public.ra_members where room_id=rid and role='candidate') then raise exception 'Candidate seat is already taken';end if;insert into public.ra_members(room_id,user_id,display_name,role) values(rid,auth.uid(),left(coalesce(nullif(trim(p_display),''),'Guest'),60),rr);return rid;end$$;
revoke all on function public.ra_create_room(text,text) from public;revoke all on function public.ra_join_room(text,text) from public;
grant execute on function public.ra_create_room(text,text),public.ra_join_room(text,text) to authenticated;
alter table public.ra_invites enable row level security;alter table public.ra_rooms enable row level security;alter table public.ra_members enable row level security;alter table public.ra_tracks enable row level security;alter table public.ra_votes enable row level security;alter table public.ra_scores enable row level security;alter table public.ra_appeals enable row level security;
drop policy if exists ra_invite_read on public.ra_invites;create policy ra_invite_read on public.ra_invites for select to authenticated using(public.ra_is_host(room_id));
drop policy if exists ra_room_read on public.ra_rooms;create policy ra_room_read on public.ra_rooms for select to authenticated using(public.ra_is_member(id));
drop policy if exists ra_room_update on public.ra_rooms;create policy ra_room_update on public.ra_rooms for update to authenticated using(public.ra_is_host(id)) with check(public.ra_is_host(id));
drop policy if exists ra_member_read on public.ra_members;create policy ra_member_read on public.ra_members for select to authenticated using(public.ra_is_member(room_id));
drop policy if exists ra_track_read on public.ra_tracks;create policy ra_track_read on public.ra_tracks for select to authenticated using(public.ra_is_member(room_id));
drop policy if exists ra_track_insert on public.ra_tracks;create policy ra_track_insert on public.ra_tracks for insert to authenticated with check(public.ra_is_host(room_id));
drop policy if exists ra_track_delete on public.ra_tracks;create policy ra_track_delete on public.ra_tracks for delete to authenticated using(public.ra_is_host(room_id));
drop policy if exists ra_vote_read on public.ra_votes;create policy ra_vote_read on public.ra_votes for select to authenticated using(public.ra_is_member(room_id));
drop policy if exists ra_vote_insert on public.ra_votes;create policy ra_vote_insert on public.ra_votes for insert to authenticated with check(public.ra_is_judge(room_id) and judge_id=auth.uid() and exists(select 1 from public.ra_rooms where id=room_id and phase='voting'));
drop policy if exists ra_vote_update on public.ra_votes;create policy ra_vote_update on public.ra_votes for update to authenticated using(public.ra_is_judge(room_id) and judge_id=auth.uid()) with check(public.ra_is_judge(room_id) and judge_id=auth.uid());
drop policy if exists ra_score_read on public.ra_scores;create policy ra_score_read on public.ra_scores for select to authenticated using(public.ra_is_judge(room_id));
drop policy if exists ra_score_insert on public.ra_scores;create policy ra_score_insert on public.ra_scores for insert to authenticated with check(public.ra_is_judge(room_id) and judge_id=auth.uid());
drop policy if exists ra_score_update on public.ra_scores;create policy ra_score_update on public.ra_scores for update to authenticated using(public.ra_is_judge(room_id) and judge_id=auth.uid() and submitted=false) with check(public.ra_is_judge(room_id) and judge_id=auth.uid());
drop policy if exists ra_appeal_read on public.ra_appeals;create policy ra_appeal_read on public.ra_appeals for select to authenticated using(public.ra_is_member(room_id));
drop policy if exists ra_appeal_insert on public.ra_appeals;create policy ra_appeal_insert on public.ra_appeals for insert to authenticated with check(public.ra_is_member(room_id) and user_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit) values('ra-audio','ra-audio',true,52428800) on conflict(id) do nothing;
drop policy if exists ra_audio_upload on storage.objects;create policy ra_audio_upload on storage.objects for insert to authenticated with check(bucket_id='ra-audio' and public.ra_is_host((split_part(name,'/',1))::uuid));
drop policy if exists ra_audio_delete on storage.objects;create policy ra_audio_delete on storage.objects for delete to authenticated using(bucket_id='ra-audio' and public.ra_is_host((split_part(name,'/',1))::uuid));
create or replace function public.ra_candidate_update(p_room uuid,p_skips text[] default null,p_ready boolean default null) returns void language plpgsql security definer set search_path=public as $$declare ph text; old_skips text[];begin if not exists(select 1 from public.ra_members where room_id=p_room and user_id=auth.uid() and role='candidate') then raise exception 'Candidate only';end if;select phase,skips into ph,old_skips from public.ra_rooms where id=p_room for update;if p_skips is not null then if ph<>'preparation' then raise exception 'Skip changes are closed';end if;if cardinality(p_skips)>2 or 'vocal'=any(p_skips) or exists(select 1 from unnest(p_skips) k where k not in ('rap','expression','pitch')) then raise exception 'Invalid skip selection';end if;update public.ra_rooms set skips=p_skips,updated_at=now() where id=p_room;end if;if p_ready is not null then if ph not in ('preparation','break') then raise exception 'Not in preparation';end if;update public.ra_rooms set ready=p_ready,updated_at=now() where id=p_room;end if;end$$;
revoke all on function public.ra_candidate_update(uuid,text[],boolean) from public;grant execute on function public.ra_candidate_update(uuid,text[],boolean) to authenticated;
drop policy if exists ra_vote_update on public.ra_votes;create policy ra_vote_update on public.ra_votes for update to authenticated using(public.ra_is_judge(room_id) and judge_id=auth.uid() and exists(select 1 from public.ra_rooms where id=room_id and phase='voting')) with check(public.ra_is_judge(room_id) and judge_id=auth.uid());

alter table public.ra_invites add column if not exists judge_code text;
alter table public.ra_invites add column if not exists candidate_code text;
update public.ra_invites set judge_code = upper(substr(replace(pg_catalog.gen_random_uuid()::text,'-',''),1,12)) where judge_code is null;
update public.ra_invites set candidate_code = upper(substr(replace(pg_catalog.gen_random_uuid()::text,'-',''),1,12)) where candidate_code is null;
create unique index if not exists ra_invites_judge_code_unique on public.ra_invites(judge_code);
create unique index if not exists ra_invites_candidate_code_unique on public.ra_invites(candidate_code);
create or replace function public.ra_create_room(p_name text,p_display text) returns uuid language plpgsql security definer set search_path=public as $$
declare rid uuid;begin
if auth.uid() is null then raise exception 'Bạn cần đăng nhập';end if;
insert into public.ra_rooms(name,host_id) values(left(coalesce(nullif(trim(p_name),''),'Audition'),100),auth.uid()) returning id into rid;
insert into public.ra_invites(room_id,judge_token,candidate_token,judge_code,candidate_code) values(rid,replace(pg_catalog.gen_random_uuid()::text,'-','')||replace(pg_catalog.gen_random_uuid()::text,'-',''),replace(pg_catalog.gen_random_uuid()::text,'-','')||replace(pg_catalog.gen_random_uuid()::text,'-',''),upper(substr(replace(pg_catalog.gen_random_uuid()::text,'-',''),1,12)),upper(substr(replace(pg_catalog.gen_random_uuid()::text,'-',''),1,12)));
insert into public.ra_members(room_id,user_id,display_name,role) values(rid,auth.uid(),left(coalesce(nullif(trim(p_display),''),'Host'),60),'host');return rid;end$$;
create or replace function public.ra_join_by_code(p_code text,p_display text) returns uuid language plpgsql security definer set search_path=public as $$
declare rid uuid; rr text; normalized text;begin
if auth.uid() is null then raise exception 'Bạn cần đăng nhập';end if;
normalized:=upper(regexp_replace(coalesce(p_code,''),'\s','','g'));
select room_id,case when judge_code=normalized then 'judge' else 'candidate' end into rid,rr from public.ra_invites where judge_code=normalized or candidate_code=normalized limit 1;
if rid is null then raise exception 'Mã mời không hợp lệ';end if;
if exists(select 1 from public.ra_members where room_id=rid and user_id=auth.uid()) then return rid;end if;
if rr='candidate' and exists(select 1 from public.ra_members where room_id=rid and role='candidate') then raise exception 'Phòng đã có thí sinh';end if;
insert into public.ra_members(room_id,user_id,display_name,role) values(rid,auth.uid(),left(coalesce(nullif(trim(p_display),''),'Khách'),60),rr);return rid;end$$;
revoke all on function public.ra_join_by_code(text,text) from public;
grant execute on function public.ra_join_by_code(text,text) to authenticated;
notify pgrst, 'reload schema';
